#!/usr/bin/env bash
# Start the local Shuffle lab. Generates per-install secrets into .env.local on first run.
set -euo pipefail
cd "$(dirname "$0")"

env_file=.env.local
random() { LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom | head -c "$1"; }

if [[ ! -f $env_file ]]; then
  umask 077
  cat >"$env_file" <<EOF
# Generated by up.sh for this machine only. Do not commit.
SHUFFLE_ADMIN_USERNAME=admin
SHUFFLE_ADMIN_PASSWORD=$(random 24)
SHUFFLE_API_KEY=$(uuidgen | tr 'A-Z' 'a-z')
SHUFFLE_ENCRYPTION_MODIFIER=$(random 32)
# OpenSearch requires upper and lower case letters, a digit and a symbol.
SHUFFLE_OPENSEARCH_PASSWORD=$(random 24)aA1!
EOF
  echo "Generated $PWD/$env_file"
fi

set -a
# shellcheck source=/dev/null
source "$env_file"
set +a
api="http://127.0.0.1:${SHUFFLE_API_PORT:-5001}/api/v1"

docker compose --env-file "$env_file" up -d

printf 'Waiting for the Shuffle API'
for _ in $(seq 1 90); do
  if curl -sf "$api/_ah/health" >/dev/null 2>&1; then break; fi
  printf '.'
  sleep 5
done
echo
curl -sf "$api/_ah/health" >/dev/null || { echo "Shuffle API did not come up; see: docker compose logs backend" >&2; exit 1; }

# On a fresh install the API answers before the admin user and API key exist.
printf 'Waiting for the admin user and API key'
for _ in $(seq 1 60); do
  status=$(curl -s -o /dev/null -w '%{http_code}' -H "Authorization: Bearer $SHUFFLE_API_KEY" "$api/workflows")
  [[ $status == 200 ]] && break
  printf '.'
  sleep 5
done
echo
[[ $status == 200 ]] || { echo "API key rejected (HTTP $status); see: docker compose logs backend" >&2; exit 1; }

# Shuffle downloads its apps on first start; workflows need at least "Shuffle Tools".
printf 'Waiting for Shuffle to load its apps'
for _ in $(seq 1 60); do
  [[ $(curl -s -H "Authorization: Bearer $SHUFFLE_API_KEY" "$api/apps") != "[]" ]] && break
  printf '.'
  sleep 5
done
echo
if [[ $(curl -s -H "Authorization: Bearer $SHUFFLE_API_KEY" "$api/apps") == "[]" ]]; then
  echo "Shuffle has not loaded its apps yet; see 'No apps loaded' in README.md." >&2
fi

cat <<EOF

Shuffle is running.
  Web UI:  http://localhost:${SHUFFLE_UI_PORT:-3001}  (user: $SHUFFLE_ADMIN_USERNAME, password in $PWD/$env_file)
  API:     $api

For anysoar's Shuffle driver:
  export SHUFFLE_URL=http://127.0.0.1:${SHUFFLE_API_PORT:-5001}
  export SHUFFLE_API_KEY="\$(grep ^SHUFFLE_API_KEY= $PWD/$env_file | cut -d= -f2)"

Stop with ./down.sh (add --purge to delete its data and secrets).
EOF
